onMounted(()=>{const render=()=>{document.querySelectorAll('.wa-math:not([data-typeset])').forEach(el=>{el.textContent=`\\[${el.dataset.tex}\\]`;el.dataset.typeset='pending'});let a=document.querySelector('.wa-article');if(window.MathJax?.typesetPromise&&a)window.MathJax.typesetPromise([a]).then(()=>document.querySelectorAll('.wa-math[data-typeset="pending"]').forEach(e=>e.dataset.typeset='done'))};if(window.MathJax?.startup?.promise)window.MathJax.startup.promise.then(render);else window.addEventListener('load',render,{once:true})})
</script>
